mermaid:
classDiagram
  class n0["Check run"] {
    <<aggregate root>>
    Checker release : version
    Core version : version
    Not checked : string
    Outcome : string
  }
  class n1["Check"] {
    <<entity>>
    Name : string
    Rule : string
  }
  class n2["Finding"] {
    <<value object>>
    Where : string
    What : string
  }
  class n3["Vocabulary"] {
    <<value object>>
    Types : string
    Units : string
  }
  class n4["Tooling pin"] {
    <<value object>>
    Tooling : version
    Core version : version
    Packs : string
  }
  class n5["Instance checked"] {
    <<domain event>>
  }
  class n6["Run refused"] {
    <<domain event>>
  }
  n0 *-- "1..*" n1
  n0 *-- "*" n2
  n0 *-- "1" n3
  n0 *-- "1" n4
  n0 ..> n5 : emits
  n0 ..> n6 : emits
